/**
 * Issue "blocked by" links.
 */
import { and, eq } from "drizzle-orm";
import { getDb, issueDependencies } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { IssueDependencyRow } from "@/server/db/schema/issue-dependencies";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { IssueDependency } from "@/types/issue";

function toDependency(row: IssueDependencyRow): IssueDependency {
  return {
    orgId: row.orgId as OrgId,
    issueId: row.issueId as IssueId,
    blockerId: row.blockerId as IssueId,
    createdBy: row.createdBy as UserId,
    createdAt: toIsoTimestamp(new Date(row.createdAt)),
  };
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toDependency(row) : null;
}

export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: new Date().toISOString(),
    })
    .returning()
    .get();
  return toDependency(row);
}

export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning()
    .all();
  return rows.length > 0;
}

/** Links where `issueId` is the blocked issue. */
export async function listDependenciesOf(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueDependency[]> {
  return getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all()
    .map(toDependency);
}

/** Links where `blockerId` is the blocker. */
export async function listDependenciesBlockedBy(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueDependency[]> {
  return getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all()
    .map(toDependency);
}
