/**
 * Issue dependencies ("blocked by" links): cycle-free links, the completion gate and the unblocked notification.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as depRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { notify } from "./notification-service";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Unsubscribe } from "@/types/event";

export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    issueId: IssueId,
    readonly blockerIds: readonly IssueId[],
  ) {
    super(`Issue ${issueId} is blocked by open issues: ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
  }
}

interface LinkInput {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
}

function isClosed(issue: Issue): boolean {
  return (
    isArchived(issue) || issue.status === "done" || issue.status === "canceled"
  );
}

async function loadIssue(orgId: OrgId, id: IssueId): Promise<Issue> {
  return requireFound(await issueRepo.findIssueById(orgId, id), "Issue", id);
}

/** Ids of the blockers of `issueId` that are still open. */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const links = await depRepo.listDependenciesOf(orgId, issueId);
  const open: IssueId[] = [];
  for (const link of links) {
    const blocker = await issueRepo.findIssueById(orgId, link.blockerId);
    if (blocker && !isClosed(blocker)) open.push(blocker.id);
  }
  return open;
}

export async function addBlocker(
  actor: Actor,
  input: LinkInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);
  const issue = await loadIssue(input.orgId, input.issueId);
  const blocker = await loadIssue(input.orgId, input.blockerId);
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (issue.id === blocker.id) {
    throw new Error("An issue cannot block itself");
  }

  const existing = await depRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  // A cycle appears when `issue` is already reachable through blocker chains.
  const seen = new Set<string>([blocker.id]);
  const stack: IssueId[] = [blocker.id];
  while (stack.length > 0) {
    const current = stack.pop() as IssueId;
    for (const link of await depRepo.listDependenciesOf(input.orgId, current)) {
      if (link.blockerId === issue.id) {
        throw new Error("This dependency would create a cycle");
      }
      if (!seen.has(link.blockerId)) {
        seen.add(link.blockerId);
        stack.push(link.blockerId);
      }
    }
  }

  return depRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: LinkInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);
  const issue = await loadIssue(input.orgId, input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  return depRepo.deleteDependency(input.orgId, input.issueId, input.blockerId);
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);
  const issue = await loadIssue(orgId, issueId);
  assertCan(actor, "issue:read", issueResource(issue));

  const blockers: Issue[] = [];
  for (const link of await depRepo.listDependenciesOf(orgId, issueId)) {
    const blocker = await issueRepo.findIssueById(orgId, link.blockerId);
    if (blocker && !isArchived(blocker)) blockers.push(blocker);
  }
  return blockers.sort((a, b) => a.number - b.number);
}

async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: Actor["userId"] | null,
): Promise<void> {
  for (const link of await depRepo.listDependenciesBlockedBy(orgId, blockerId)) {
    const blocked = await issueRepo.findIssueById(orgId, link.issueId);
    if (!blocked || isClosed(blocked) || blocked.assigneeId === null) continue;
    if ((await listOpenBlockerIds(orgId, blocked.id)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

const OPEN_CLOSED = new Set(["done", "canceled"]);

export function registerDependencyListeners(): Unsubscribe {
  const offs = [
    subscribe("issue.status_changed", async (payload) => {
      if (OPEN_CLOSED.has(payload.from) || !OPEN_CLOSED.has(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      if (payload.previousStatus === undefined) return;
      if (OPEN_CLOSED.has(payload.previousStatus)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];
  return () => {
    for (const off of offs) off();
  };
}
